import { AVAILABLE_FILTERS, COLLECTION_PRODUCTS_QUERY } from '../queries/collection-queries';
import formatProductData from '../transformers/product-transformer';

export class CollectionService {
  constructor(storefront) {
    this.storefront = storefront;
  }

  async getProducts(handle, options = {}) {
    let {
      first = 12,
      last = null,
      before = null,
      after = null,
      sortKey = 'COLLECTION_DEFAULT',
      reverse = false,
      filters = [],
    } = options;

    // Determine if it's backward pagination
    if (before) {
      first = null; // Clear `first`
    } else {
      last = null;
    }

    const variables = {
      handle,
      first,
      last,
      before,
      after,
      sortKey,
      reverse,
      filters,
    };

    const result = await this.storefront.query(
      COLLECTION_PRODUCTS_QUERY,
      variables,
    );

    if (!result.ok) {
      throw result.error;
    }

    if (!result.data?.collection) {
      throw new Error('Collection not found');
    }

    const { collection } = result.data;
    const products = collection.products.nodes.map(formatProductData);
    const availableFilter = result.data.collection.products.filters;

    return {
      products,
      pageInfo: collection.products.pageInfo,
      availableFilter,
    };
  }

  async getavailableFilters(handle, options = {}) {
    const {
      first = 12,
      after = null,
      filters = [],
    } = options;

    const variables = {
      handle,
      first,
      after,
      filters,
    };

    const result = await this.storefront.query(
      AVAILABLE_FILTERS,
      variables,
    );

    if (!result.ok) {
      throw result.error;
    }

    if (!result.data?.collection) {
      throw new Error('Collection not found');
    }

    const { collection } = result.data;
    const availableFilter = result.data.collection.products.filters;

    return {
      pageInfo: collection.products.pageInfo,
      availableFilter,
    };
  }
}

export class VariantSelectorService {
  constructor(product) {
    this.product = product;
    this.variants = product?.variants || [];
  }

  /**
   * Returns unique option names from variants
   */
  getOptionNames() {
    const names = new Set();
    this.variants.forEach((v) => {
      (v.selectedOptions || []).forEach((o) => names.add(o.name));
    });
    return Array.from(names);
  }

  /**
   * Returns all values for a specific option name
   */
  getOptionValues(optionName) {
    const values = new Set();
    this.variants.forEach((v) => {
      v.selectedOptions?.forEach((o) => {
        if (o.name === optionName) {
          values.add(o.value);
        }
      });
    });
    return Array.from(values);
  }

  /**
   * Finds the matching variant for selected options
   */
  findMatchingVariant(selectedOptions) {
    return (
      this.variants.find((v) =>
        v.selectedOptions.every(
          (o) => selectedOptions[o.name] === o.value,
        ),
      ) || null
    );
  }
}
