import formatMoney from './format-money';
import { getLogger } from '~/lib/log';
import { storeKeys } from '../mixins/base-listing-mixin';

const log = getLogger('collectionProductData');

export default function collectionProductData(config = {}) {
  const base = storeKeys(config);

  return {
    ...base,
    products: [],
    hasNextPage: false,
    hasPreviousPage: false,
    endCursor: null,
    startCursor: null,
    pageStartCursor: null,
    pageEndCursor: null,
    collectionService: null,
    moneyFormatter: formatMoney,
    collectionHandle: config.collectionHandle || '',
    availableFilter: [],
    selectedFilters: {},
    gridMode: 'minimal',
    loading: false,
    toast: {
      visible: false,
      message: '',
    },
    filteropen: false,
    locale: {},
    currentSort: {
      key: 'COLLECTION_DEFAULT', labelkey: 'featured', sortKey: 'COLLECTION_DEFAULT', reverse: false,
    },
    sortOptions: [
      {
        key: 'COLLECTION_DEFAULT', labelkey: 'featured', sortKey: 'COLLECTION_DEFAULT', reverse: false,
      },
      {
        key: 'TITLE_ASC', labelkey: 'a_z', sortKey: 'TITLE', reverse: false,
      },
      {
        key: 'TITLE_DESC', labelkey: 'z_a', sortKey: 'TITLE', reverse: true,
      },
      {
        key: 'PRICE_ASC', labelkey: 'price_low_high', sortKey: 'PRICE', reverse: false,
      },
      {
        key: 'PRICE_DESC', labelkey: 'price_high_low', sortKey: 'PRICE', reverse: true,
      },
      {
        key: 'CREATED_DESC', labelkey: 'newest_first', sortKey: 'CREATED', reverse: true,
      },
      {
        key: 'CREATED_ASC', labelkey: 'oldest_first', sortKey: 'CREATED', reverse: false,
      },
    ],

    async init() {
      this.locale = JSON.parse(document.getElementById('sorting-locale').textContent);
      this.enableAutoload
        = config.enableAutoLoad === true
        || config.enableAutoLoad === 'true';
      log.info('config', config);
      log.info('enableAutoload value:', this.enableAutoload);
      const factory = this.createStorefrontFactory();
      this.collectionService = factory.createCollectionService();
      const urlParams = new URLSearchParams(window.location.search);
      const hasFilterParams = Array.from(urlParams.keys()).some(
        (key) => key.startsWith('filter.') || key.startsWith('sort_by') || key.endsWith('_cursor'),
      );
      if (hasFilterParams) {
        await this.loadProductsWithUrlFilters(urlParams);
      } else {
        await this.loadInitialProductsAndFilters();
      }

      this.$watch('products', (newVal) => {
        if (newVal && newVal.length) {
          this.$nextTick(() => this.rerenderKey++);
        }
      });
    },

    applySort(option) {
      this.currentSort = { ...option };
      this.applyFilters();
    },

    async loadProductsWithUrlFilters(urlParams) {
      if (!this.collectionService) {
        return;
      }

      this.setLoadingState(true);
      const filtersPayload = [];
      this.selectedFilters = {};

      try {
        const baseResult = await this.collectionService.getavailableFilters(this.collectionHandle, { first: 1 });
        this.availableFilter = baseResult?.availableFilter || [];
        urlParams.forEach((value, key) => {
          const filterId = `${key}.${value}`;

          this.availableFilter.forEach((filter) => {
            filter.values.forEach((v) => {
              if (v.id === filterId) {
                this.selectedFilters[filter.label] ||= [];
                this.selectedFilters[filter.label].push(v);

                try {
                  const parsedInput = JSON.parse(v.input);
                  filtersPayload.push(parsedInput);
                } catch (err) {
                  log.warn('Failed to parse input for', v.label, err);
                }
              }
            });
          });
          this.sortOptions.forEach((sort) => {
            if (sort.key === value) {
              this.currentSort = sort;
            }
          });
        });

        // Handle PRICE_RANGE filters
        const priceMin = urlParams.get('filter.price_min');
        const priceMax = urlParams.get('filter.price_max');

        if (priceMin || priceMax) {
          const priceValues = {
            type: 'PRICE_RANGE',
            min: parseFloat(priceMin || 0),
            max: parseFloat(priceMax || 1000),
          };
          this.selectedFilters.PriceMin = priceValues.min;
          this.selectedFilters.PriceMax = priceValues.max;
          filtersPayload.push({ price: { min: priceValues.min, max: priceValues.max } });
        }

        const object = {
          filters: filtersPayload,
          first: Number(this.productsPerPage),
          last: Number(this.productsPerPage),
          sortKey: this.currentSort.sortKey,
          reverse: this.currentSort.reverse,
          after: urlParams.get('start_cursor') || null,
          before: urlParams.get('end_cursor') || null,
        };
        // Fetch products
        const result = await this.collectionService.getProducts(this.collectionHandle, object);

        this.products = result?.products || [];
        this.availableFilter = result?.availableFilter || this.availableFilter;
        this.hasNextPage = result?.pageInfo?.hasNextPage ?? false;
        this.hasPreviousPage = result?.pageInfo?.hasPreviousPage ?? false;
        this.startCursor = result?.pageInfo?.startCursor ?? null;
        this.endCursor = result?.pageInfo?.endCursor ?? null;
        log.info('hasNextPage: ', this.hasNextPage, 'this.hasPreviousPage: ', this.hasPreviousPage);
      } catch (error) {
        this.error = error.message;
        log.error('Error loading URL-filtered products:', error);
      } finally {
        this.loading = false;
      }
    },

    updateUrlParams() {
      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.startsWith('sort_by')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      Object.entries(this.selectedFilters).forEach(([label, values]) => {
        if (label === 'price' && values?.min !== undefined) {
          url.searchParams.set('filter.price_min', values.min);
          url.searchParams.set('filter.price_max', values.max);
        } else if (Array.isArray(values)) {
          values.forEach((v) => {
            const parts = v.id.split('.');
            const key = parts.slice(0, -1).join('.');
            const val = parts[parts.length - 1];
            url.searchParams.append(key, val);
          });
        }
      });

      // Add sort
      url.searchParams.set('sort_by', this.currentSort.key);

      // Add pagination cursors
      if (this.pageStartCursor) {
        url.searchParams.set('start_cursor', this.pageStartCursor);
      } else {
        url.searchParams.delete('start_cursor');
      }

      // Update or remove end_cursor
      if (this.pageEndCursor) {
        url.searchParams.set('end_cursor', this.pageEndCursor);
      } else {
        url.searchParams.delete('end_cursor');
      }

      // Update URL without reloading page
      window.history.replaceState({}, '', url);
    },
    async loadInitialProductsAndFilters() {
      if (!this.collectionService) {
        return;
      }

      try {
        this.setLoadingState(true);
        const result = await this.collectionService.getProducts(this.collectionHandle, {
          first: Number(this.productsPerPage),
        });

        this.availableFilter = result?.availableFilter || [];
        this.products = result?.products || [];
        this.hasNextPage = result?.pageInfo?.hasNextPage || false;
        this.hasPreviousPage = result?.pageInfo?.hasPreviousPage ?? false;
        this.startCursor = result?.pageInfo?.startCursor ?? null;
        this.endCursor = result?.pageInfo?.endCursor || null;
      } catch (error) {
        this.error = error.message;
        log.error('Error loading products:', error);
      } finally {
        this.loading = false;
      }
    },

    toggleFilter(label, value, input, id) {
      this.selectedFilters[label] ||= [];
      const index = this.selectedFilters[label].findIndex((v) => v.label === value);

      if (index === -1) {
        this.selectedFilters[label].push({ label: value, input, id });
      } else {
        this.selectedFilters[label].splice(index, 1);
        if (this.selectedFilters[label].length === 0) {
          delete this.selectedFilters[label];
        }
      }

      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      this.applyFilters();
    },

    showToast(message, type = 'error') {
      this.toast.message = message;
      this.toast.visible = true;
      this.toast.type = type;
      setTimeout(() => {
        this.toast.visible = false;
      }, 2500);
    },
    removePriceFilter() {
      delete this.selectedFilters.PriceMin;
      delete this.selectedFilters.PriceMax;
      delete this.selectedFilters.price;
      this.applyFilters();
    },
    validatePriceRange(filter, field) {
      const priceData = JSON.parse(filter.values[0].input).price;
      const minAllowed = parseFloat(priceData.min);
      const maxAllowed = parseFloat(priceData.max);

      const min = parseFloat(this.selectedFilters.PriceMin);
      const max = parseFloat(this.selectedFilters.PriceMax);

      if (field === 'min' && (min < minAllowed || min > maxAllowed)) {
        this.showToast(this.locale.minvalue_error_range
          .replace('{min}', minAllowed)
          .replace('{max}', maxAllowed),
        'error');
        this.selectedFilters.PriceMin = null;
        return;
      }

      if (field === 'max' && (max < minAllowed || max > maxAllowed)) {
        this.showToast(this.locale.maxvalue_error_range
          .replace('{min}', minAllowed)
          .replace('{max}', maxAllowed));
        this.selectedFilters.PriceMax = null;
        return;
      }

      if (min && max && max < min) {
        this.showToast(this.locale.max_greater_than_min);
        if (field === 'max') {
          this.selectedFilters.PriceMax = null;
        } else {
          this.selectedFilters.PriceMin = null;
        }

        return;
      }

      this.applyPriceFilter();
    },
    applyPriceFilter() {
      if (!this.availableFilter || !Array.isArray(this.availableFilter)) {
        log.warn('availableFilters not loaded yet');
        return;
      }

      const priceFilter = this.availableFilter.find((f) => f.type === 'PRICE_RANGE');
      let min;
      let max;
      if (priceFilter) {
        const priceData = JSON.parse(priceFilter.values[0].input).price;
        min = parseFloat(this.selectedFilters.PriceMin ?? priceData.min);
        max = parseFloat(this.selectedFilters.PriceMax ?? priceData.max);
        this.selectedFilters.PriceMin = min;
        this.selectedFilters.PriceMax = max;
      }

      this.selectedFilters.price = { min, max };
      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      this.applyFilters();
    },
    removeSingleFilter(label, filterObj) {
      if (this.selectedFilters[label]) {
        const index = this.selectedFilters[label].findIndex((f) => f.id === filterObj.id);
        if (index !== -1) {
          this.selectedFilters[label].splice(index, 1);
        }

        if (this.selectedFilters[label].length === 0) {
          delete this.selectedFilters[label];
        }
      }

      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      this.applyFilters();
      this.updateUrlParams();
    },
    clearAllFilters() {
      this.selectedFilters = {};
      this.products = [];
      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      this.applyFilters();
      this.updateUrlParams();
    },

    async applyFilters() {
      try {
        this.setLoadingState(true);
        this.products = [];

        const filtersPayload = this.getFiltersPayload();
        const urlParams = new URLSearchParams(window.location.search);
        const options = {
          filters: filtersPayload,
          first: Number(this.productsPerPage),
          last: Number(this.productsPerPage),
          sortKey: this.currentSort.sortKey,
          reverse: this.currentSort.reverse,
          after: urlParams?.get('start_cursor') || null,
          before: urlParams?.get('end_cursor') || null,
        };
        const baseResult = await this.collectionService.getavailableFilters(this.collectionHandle, { first: 1 });
        this.availableFilter = baseResult?.availableFilter || [];
        const result = await this.collectionService.getProducts(this.collectionHandle, options);

        this.products = result?.products || [];
        this.hasNextPage = result?.pageInfo?.hasNextPage || false;
        this.hasPreviousPage = result?.pageInfo?.hasPreviousPage ?? false;
        this.startCursor = result?.pageInfo?.startCursor ?? null;
        this.endCursor = result?.pageInfo?.endCursor || null;
        this.updateUrlParams();
      } catch (error) {
        this.error = error.message;
        log.error('Error applying filters:', error);
      } finally {
        this.loading = false;
      }
    },
    async nextPage(isInfinite = false) {
      if (!this.collectionService) {
        return;
      }

      this.pageEndCursor = null;

      const filtersPayload = this.getFiltersPayload();
      const object = {
        filters: filtersPayload,
        first: Number(this.productsPerPage), // Number of products to fetch
        sortKey: this.currentSort.sortKey,
        reverse: this.currentSort.reverse,
        after: this.endCursor, // Fetch items **after** current end
      };

      try {
        const result = await this.collectionService.getProducts(this.collectionHandle, object);
        const productsData = result?.products;

        if (productsData) {
          if (isInfinite) {
            this.products.push(...productsData);
          } else {
            this.products = productsData;
            this.pageStartCursor = this.endCursor;
            this.updateUrlParams();
          }

          const pageInfo = result?.pageInfo;
          this.hasNextPage = pageInfo.hasNextPage;
          this.hasPreviousPage = pageInfo.hasPreviousPage;
          this.startCursor = pageInfo.startCursor;
          this.endCursor = pageInfo.endCursor;
        }
      } catch (err) {
        log.error('Error fetching next page:', err);
      } finally {
        this.loading = false;
      }
    },
    async prevPage() {
      if (!this.collectionService) {
        return;
      }

      this.pageStartCursor = null;

      const filtersPayload = this.getFiltersPayload();

      const object = {
        filters: filtersPayload,
        last: Number(this.productsPerPage), // Number of products to fetch
        sortKey: this.currentSort.sortKey,
        reverse: this.currentSort.reverse,
        before: this.startCursor, // Fetch items **before** current start
      };
      this.pageEndCursor = this.startCursor;

      try {
        const result = await this.collectionService.getProducts(this.collectionHandle, object);
        const productsData = result?.products;

        if (productsData) {
          this.products = productsData; // Replace current products with previous page
          const pageInfo = result?.pageInfo;
          this.hasNextPage = pageInfo.hasNextPage;
          this.hasPreviousPage = pageInfo.hasPreviousPage;
          this.startCursor = pageInfo.startCursor;
          this.endCursor = pageInfo.endCursor;
        }

        this.updateUrlParams();
      } catch (err) {
        log.error('Error fetching previous page:', err);
      }
    },

    // helper to get filters payload
    getFiltersPayload() {
      const filtersPayload = [];
      Object.entries(this.selectedFilters).forEach(([label, values]) => {
        if (label === 'price') {
          filtersPayload.push({ price: values });
        } else if (Array.isArray(values)) {
          values.forEach((v) => {
            try {
              filtersPayload.push(JSON.parse(v.input));
            } catch (err) {
              log.warn('Failed to parse filter input:', v.input, err);
            }
          });
        }
      });
      return filtersPayload;
    },
  };
}
