import { ShopifyStorefront } from '../lib/api/shopify-storefront';
import { CollectionService, VariantSelectorService } from '../services/collection-service';

export class StorefrontFactory {
  constructor(config) {
    this.storefront = new ShopifyStorefront(config);
  }

  createCollectionService() {
    return new CollectionService(this.storefront);
  }

  createVariantService() {
    return new VariantSelectorService(this.storefront);
  }
}
